  'help.type.security': 'Security',
  'help.type.other': 'Other',
  'help.faq.cantLogin.q': 'I can\'t log in to my account',
  'help.faq.cantLogin.a': 'Make sure you\'re using the correct email and password. If you forgot your password, click "Forgot password?" on the login screen. If the problem persists, create a support ticket.',
  'help.faq.notReceiving.q': 'I\'m not receiving emails',
  'help.faq.notReceiving.a': 'Check your Spam folder first. Make sure your storage isn\'t full. If the issue continues, verify that the sender has the correct email address and create a support ticket.',
  'help.faq.cantSend.q': 'I can\'t send emails',
  'help.faq.cantSend.a': 'Verify your internet connection and that the recipient\'s email address is correct. Check if you have any attachments that are too large (max 25MB). Try again in a few minutes.',
  'help.faq.forgotPassword.q': 'I forgot my password',
  'help.faq.forgotPassword.a': 'On the login screen, click "Forgot password?" and follow the instructions to reset your password via your recovery email address.',
  'help.faq.accountSecurity.q': 'I think my account was compromised',
  'help.faq.accountSecurity.a': 'Immediately change your password. Check your Sent folder for messages you didn\'t send. Enable two-factor authentication in Settings > Security. If needed, create an urgent support ticket.',
  'help.faq.appAccess.q': 'How do I access the app on mobile?',
  'help.faq.appAccess.a': 'You can access Chatyy via any mobile browser at chatyy.com.br, or download our app from your device\'s app store.',

  // Privacy modal
  'privacy.title': 'Privacy Policy',
  'privacy.subtitle': 'How we protect and handle your data',
  'privacy.lastUpdated': 'Last updated: March 2026',
  'privacy.dataCollection.title': 'Data Collection',
  'privacy.dataCollection.body': 'We collect only the information necessary to provide our email service: your name, email address, and the content of messages you send and receive. We do not sell or share your personal data with third parties for marketing purposes.',
  'privacy.dataUsage.title': 'How We Use Your Data',
  'privacy.dataUsage.body': 'Your data is used exclusively to operate and improve the email service, including delivering messages, filtering spam, providing AI-powered features (with your consent), and maintaining account security.',
  'privacy.dataSecurity.title': 'Data Security',
  'privacy.dataSecurity.body': 'We use industry-standard encryption (TLS/SSL) for all data in transit and at rest. Sessions are protected with encrypted tokens and CSRF protection. We regularly audit our security practices.',
  'privacy.cookies.title': 'Cookies & Local Storage',
  'privacy.cookies.body': 'We use essential cookies and local storage to maintain your session, remember your preferences (theme, language), and provide a seamless experience. We do not use tracking cookies from third parties.',
  'privacy.thirdParties.title': 'Third-Party Services',
  'privacy.thirdParties.body': 'We may use third-party services for specific functionality such as AI features (Anthropic Claude) and push notifications. These services are bound by their own privacy policies and process only the minimum data required.',
  'privacy.rights.title': 'Your Rights',
  'privacy.rights.body': 'You have the right to access, correct, export, or delete your personal data at any time. You can manage your data through Settings or by contacting our support team.',
  'privacy.contact.title': 'Contact Us',
  'privacy.contact.body': 'For privacy-related questions or data requests, contact us at privacy@chatyy.com.br. We will respond within 30 days.',

  // Terms modal
  'terms.title': 'Terms of Service',
  'terms.subtitle': 'Guidelines for using Chatyy',
  'terms.lastUpdated': 'Last updated: March 2026',
  'terms.acceptance.title': 'Acceptance of Terms',
  'terms.acceptance.body': 'By accessing or using Chatyy, you agree to be bound by these Terms of Service. If you do not agree with any part of these terms, you may not use the service.',
  'terms.services.title': 'Description of Services',
  'terms.services.body': 'Chatyy provides email communication services including sending, receiving, and managing emails, along with AI-powered features, calendar integration, and video conferencing capabilities.',
  'terms.accounts.title': 'User Accounts',
  'terms.accounts.body': 'You are responsible for maintaining the security of your account credentials. You must not share your password or allow unauthorized access to your account. You must be at least 13 years old to use this service.',
  'terms.conduct.title': 'Acceptable Use',
  'terms.conduct.body': 'You agree not to use the service for sending spam, malware, phishing, or any illegal content. You must not attempt to access other users\' accounts or disrupt the service infrastructure.',
  'terms.content.title': 'Content Ownership',
  'terms.content.body': 'You retain ownership of all content you create and send through the service. We do not claim ownership over your emails or attachments. We may process content as necessary to provide the service.',
  'terms.limitation.title': 'Limitation of Liability',
  'terms.limitation.body': 'Chatyy is provided "as is". We strive for 99.9% uptime but do not guarantee uninterrupted service. We are not liable for any indirect, incidental, or consequential damages arising from your use of the service.',
  'terms.termination.title': 'Account Termination',
  'terms.termination.body': 'We may suspend or terminate accounts that violate these terms. You may delete your account at any time through Settings. Upon termination, your data will be deleted within 30 days.',
  'terms.changes.title': 'Changes to Terms',
  'terms.changes.body': 'We may update these terms from time to time. We will notify you of significant changes via email or in-app notification. Continued use of the service after changes constitutes acceptance of the updated terms.',

